create or replace function public.rr_material_bom_apply_v660(p_canonical_lot_id text,p_good_pcs numeric,p_source_record_id text,p_data_mode text default 'TEST') returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare l record;v_cat text;z record;m record;s record;v_qty numeric;v_rate numeric;v_total numeric;v_done jsonb:='[]';
begin if coalesce(p_good_pcs,0)<=0 then return jsonb_build_object('ok',true,'consumed',v_done);end if;select * into l from public.rr_upm_lot_registry where canonical_lot_id=p_canonical_lot_id;if not found then raise exception 'Lot not found';end if;select upper(coalesce(a.category,'')) into v_cat from public.rr_art_master a where a.id=l.art_id;
for z in select distinct on(x.material_id) x.* from public.rr_material_consumption_mapping_v655 x where x.is_active and x.consumption_method='BOM_AUTO' and x.effective_from<=current_date and (upper(x.category_code)='ALL' or upper(x.category_code)=v_cat) order by x.material_id,case when upper(x.category_code)=v_cat then 0 else 1 end,x.effective_from desc,x.id desc loop
select * into m from public.rr_material_master_v805 where id=z.material_id and is_active;select * into s from public.rr_material_stock_v805 where material_id=z.material_id and upper(data_mode)=upper(p_data_mode);v_qty:=p_good_pcs*z.qty_per_piece;v_rate:=s.weighted_avg_rate_per_consumption_unit;if coalesce(v_rate,0)<=0 then raise exception 'Weighted purchase rate missing for BOM material %.',m.material_name;end if;v_total:=v_qty*v_rate;
insert into public.rr_material_consumption_v805(material_id,source_module,source_record_id,lot_no,applicable_qty,consumption_qty,consumption_unit,base_qty_consumed,weighted_rate_per_base_unit,weighted_rate_per_consumption_unit,cost_per_good_piece,total_consumption_cost,consumption_basis,data_mode) values(m.id,'CATEGORY_BOM',p_source_record_id,l.lot_no,p_good_pcs,v_qty,m.consumption_unit,v_qty*coalesce(m.consumption_to_base,1),s.weighted_avg_rate_per_base_unit,v_rate,v_total/p_good_pcs,v_total,'CATEGORY_BOM:'||coalesce(v_cat,'PROVISION'),upper(p_data_mode)) on conflict(material_id,source_module,source_record_id,data_mode) do update set applicable_qty=excluded.applicable_qty,consumption_qty=excluded.consumption_qty,base_qty_consumed=excluded.base_qty_consumed,weighted_rate_per_base_unit=excluded.weighted_rate_per_base_unit,weighted_rate_per_consumption_unit=excluded.weighted_rate_per_consumption_unit,cost_per_good_piece=excluded.cost_per_good_piece,total_consumption_cost=excluded.total_consumption_cost;
v_done:=v_done||jsonb_build_array(jsonb_build_object('material_id',m.id,'material_name',m.material_name,'qty',v_qty,'unit',m.consumption_unit,'weighted_rate',v_rate,'cost',v_total));end loop;
return jsonb_build_object('ok',true,'version','V660_BOM_DEDUPED_WEIGHTED','category',v_cat,'consumed',v_done,'rule','ONE LATEST EFFECTIVE MAPPING PER MATERIAL; WEIGHTED RATE REQUIRED; IDEMPOTENT LEDGER');end $function$;